files.src/LevelScale.st:
PROGRAM LevelScale
VAR_INPUT Enable AT %I0.0 : BOOL; END_VAR
VAR_OUTPUT HighLevel AT %Q0.0 : BOOL; END_VAR
VAR Raw : DINT; Level : DINT; END_VAR
IF Enable THEN Raw := MIN(Raw + 410, 4095); ELSE Raw := 0; END_IF;
Level := LIMIT(0, (Raw * 100) / 4095, 100);
HighLevel := Level >= 75;
END_PROGRAM

